package local.skyfamily;
import android.graphics.*;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
final class SavedPhotoPreview {
 final CalendarPhotosActivity host;final Handler main=new Handler();final ArrayList<Target> targets=new ArrayList<>();String key="",message="Loading photos";Bitmap bitmap;long fetched=0;int serial=0;boolean loading=false,closed=false;Source pending;int pendingSerial;
 static class Target{ImageView image;TextView label;int revision;Target(ImageView i,TextView l,int r){image=i;label=l;revision=r;}}
 static class Source{String key,server,token;boolean local,waiting;File file;ArrayList<String> albums=new ArrayList<>();}
 SavedPhotoPreview(CalendarPhotosActivity activity){host=activity;}
 void bind(ImageView image,TextView label){for(Iterator<Target> iterator=targets.iterator();iterator.hasNext();)if(iterator.next().revision!=host.revision)iterator.remove();targets.add(new Target(image,label,host.revision));refresh(false);render();}
 void clearTargets(){targets.clear();}
 Source source(){Source source=new Source();source.server=host.server;source.token=host.token;source.local=host.prefs.getBoolean("gallery.local",false)||host.token.isEmpty()&&host.get("immich.vault").isEmpty();if(source.local){File[] images=new File(host.getFilesDir(),"uploads").listFiles((directory,name)->name.endsWith(".image"));if(images!=null&&images.length>0){Arrays.sort(images,(a,b)->Long.compare(b.lastModified(),a.lastModified()));source.file=images[0];}source.key="local:"+(source.file==null?"none":source.file.getName()+":"+source.file.lastModified());}else if(source.token.isEmpty()){source.waiting=true;source.key="waiting:"+host.get("immich.vault").hashCode();}else{source.albums.addAll(host.selection());Collections.sort(source.albums);source.key=host.signature(source.server,source.token,new LinkedHashSet<String>(source.albums));}return source;}
 void refresh(boolean force){if(closed)return;Source source=source();if(force||!source.key.equals(key)){serial++;key=source.key;bitmap=null;fetched=0;loading=false;main.removeCallbacks(load);}if(source.waiting){message=Build.VERSION.SDK_INT<18?"Unlock saved photo session to load albums":"Restoring saved photo session...";render();return;}if(source.local&&source.file==null){message="No uploaded photos yet";render();return;}if(bitmap!=null&&!force&&System.currentTimeMillis()-fetched<300000){render();return;}if(loading){render();return;}loading=true;message=source.local?"Loading uploaded photo...":"Loading saved album selection...";pending=source;pendingSerial=serial;render();main.removeCallbacks(load);main.postDelayed(load,250);}
 final Runnable load=()->{final Source selected=pending;final int ticket=pendingSerial;if(selected==null||closed)return;host.work(()->{try{Bitmap image;String label;if(selected.local){image=decodeFile(selected.file);label="Uploaded photos";}else{JSONObject fallback=null,chosen=null;ArrayList<String> albums=new ArrayList<>(selected.albums);if(albums.isEmpty())albums.add("");for(String album:albums){if(ticket!=serial||closed)return;JSONObject query=new JSONObject().put("size",24).put("page",1);if(!album.isEmpty())query.put("albumIds",new JSONArray().put(album));JSONObject response=new JSONObject(new String(host.request(selected.server+"/search/metadata","POST",query.toString(),selected.token,6000000),"UTF-8"));JSONArray items=response.getJSONObject("assets").getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String id=item.optString("id");if(!id.matches("[A-Za-z0-9-]+"))continue;if(item.optString("type").equals("IMAGE")){chosen=item;break;}if(fallback==null&&item.optString("type").equals("VIDEO"))fallback=item;}if(chosen!=null)break;}if(chosen==null)chosen=fallback;if(chosen==null)throw new IOException("No media found in saved selection");byte[] bytes=host.request(selected.server+"/assets/"+chosen.getString("id")+"/thumbnail?size=preview","GET",null,selected.token,10000000);image=decode(bytes);label=(chosen.optString("type").equals("VIDEO")?"Video preview / ":"")+(selected.albums.isEmpty()?"Whole Immich library":selected.albums.size()+" saved album(s)");}final Bitmap ready=image;final String caption=label;main.post(()->{if(closed||ticket!=serial||!selected.key.equals(source().key))return;bitmap=ready;fetched=System.currentTimeMillis();loading=false;message=caption;render();});}catch(Exception error){main.post(()->{if(!closed&&ticket==serial){loading=false;message="Photos unavailable / "+error.getMessage();render();}});}catch(OutOfMemoryError error){main.post(()->{if(!closed&&ticket==serial){loading=false;message="Photos unavailable / not enough memory";render();}});}});};
 BitmapFactory.Options options(int width,int height)throws IOException{if(width<1||height<1)throw new IOException("Unsupported photo");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(width/options.inSampleSize>900||height/options.inSampleSize>700)options.inSampleSize*=2;return options;}
 Bitmap decode(byte[] bytes)throws IOException{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);Bitmap value=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options(bounds.outWidth,bounds.outHeight));if(value==null)throw new IOException("Unsupported photo");return value;}
 Bitmap decodeFile(File file)throws IOException{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),bounds);Bitmap value=BitmapFactory.decodeFile(file.getPath(),options(bounds.outWidth,bounds.outHeight));if(value==null)throw new IOException("Unsupported photo");return value;}
 void render(){for(Iterator<Target> iterator=targets.iterator();iterator.hasNext();){Target target=iterator.next();if(target.revision!=host.revision){iterator.remove();continue;}target.image.setImageBitmap(bitmap);target.label.setText(message);}}
 void failure(String text){serial++;loading=false;main.removeCallbacks(load);bitmap=null;message=text;render();}
 void clear(){failure("Photo connection cleared");key="";fetched=0;}
 void close(){closed=true;serial++;main.removeCallbacksAndMessages(null);targets.clear();bitmap=null;}
}
